ALTER TABLE tasks ADD COLUMN startMinute INTEGER;
ALTER TABLE tasks ADD COLUMN endMinute INTEGER;
ALTER TABLE tasks ADD COLUMN stage TEXT DEFAULT 'To Do';
ALTER TABLE tasks ADD COLUMN project INTEGER REFERENCES projects(id) ON DELETE SET NULL;
CREATE TABLE projects(id INTEGER PRIMARY KEY,name TEXT NOT NULL,day TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '');
CREATE TABLE personal_logs(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,day TEXT NOT NULL,name TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 0,notes TEXT NOT NULL DEFAULT '');
CREATE INDEX personal_logs_day ON personal_logs(kind,day);
CREATE TABLE budgets(id INTEGER PRIMARY KEY,month TEXT NOT NULL,category TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),UNIQUE(month,category));
CREATE TABLE focus_sessions(id INTEGER PRIMARY KEY,name TEXT NOT NULL,started INTEGER NOT NULL,ended INTEGER);
CREATE UNIQUE INDEX one_running_timer ON focus_sessions((1)) WHERE ended IS NULL;
CREATE TABLE valuations(id INTEGER PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,day TEXT NOT NULL,cost INTEGER NOT NULL CHECK(cost>=0),value INTEGER NOT NULL CHECK(value>=0));
CREATE TABLE loans(id INTEGER PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('Debt','Lending')),account INTEGER NOT NULL REFERENCES accounts(id),principal INTEGER NOT NULL CHECK(principal>0),day TEXT NOT NULL,due TEXT NOT NULL);
CREATE TABLE repayments(id INTEGER PRIMARY KEY,loan INTEGER NOT NULL REFERENCES loans(id),account INTEGER NOT NULL REFERENCES accounts(id),day TEXT NOT NULL,principal INTEGER NOT NULL CHECK(principal>=0),interest INTEGER NOT NULL CHECK(interest>=0));
DROP VIEW ledger_entries;
CREATE VIEW ledger_entries AS SELECT id AS tx,day,account AS account_id,CASE WHEN kind='Income' THEN amount ELSE -amount END AS delta FROM transactions UNION ALL SELECT id,day,destination,amount FROM transactions WHERE kind='Transfer' UNION ALL SELECT NULL,day,account,CASE WHEN kind='Debt' THEN principal ELSE -principal END FROM loans UNION ALL SELECT NULL,r.day,r.account,CASE WHEN l.kind='Debt' THEN -r.principal ELSE r.principal END FROM repayments r JOIN loans l ON l.id=r.loan;
CREATE TABLE recurring(id INTEGER PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),account INTEGER NOT NULL REFERENCES accounts(id),category INTEGER NOT NULL REFERENCES categories(id),next TEXT NOT NULL,frequency TEXT NOT NULL,anchor INTEGER NOT NULL,intervalDays INTEGER NOT NULL DEFAULT 1,paused INTEGER NOT NULL DEFAULT 0,subscription INTEGER NOT NULL DEFAULT 0);
CREATE TABLE occurrences(id INTEGER PRIMARY KEY,rule INTEGER NOT NULL REFERENCES recurring(id),day TEXT NOT NULL,UNIQUE(rule,day));
CREATE TABLE deleted_records(id INTEGER PRIMARY KEY,source TEXT NOT NULL,title TEXT NOT NULL,removed TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE subtasks(id INTEGER PRIMARY KEY,task INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,name TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0);
CREATE TABLE milestones(id INTEGER PRIMARY KEY,goal INTEGER NOT NULL REFERENCES goals(id) ON DELETE CASCADE,name TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0);
